%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% test_gmekf_correct_hopper.m
%
% One fake correct step through gmekf_correct_hopper.m with every sensor
% model valid, using measurements generated by the Src_sim models:
%   1. The step runs end to end and returns a 20x1 state and a symmetric
%      positive-definite 19x19 covariance
%   2. With a small roll offset about the vertical axis, the step with
%      differential GPS removes most of it; without DGPS it stays
%
% Sensor noise is turned off so the comparison is deterministic.
% Runs filter_sim_initializer first. Errors if any check fails.
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

testDir = fileparts(mfilename('fullpath'));
startDir = cd(fileparts(testDir));
filter_sim_initializer;
rng(2);

% Noise off for every sensor except LIDAR, whose reported covariance comes
% from its noise level (it cannot observe roll about the vertical axis)
gps_params.pos_noise_std = zeros(3,1);
gps_params.vel_noise_std = zeros(3,1);
gps_params.multipath = zeros(3,1);
imu_params.accel_noise_std = zeros(3,1);
imu_params.gyro_noise_std = zeros(3,1);
baro_params.noise_std = 0;
diffGps_params.noise_std = zeros(3,1);
clear gps_model imu_model barometer_model diffGps_model lidar_model_base

% Nominal: vertical at the origin. Truth: 2 deg roll about the vertical
% axis plus a small tilt, everything else equal.
xNominal = zeros(20,1);
xNominal(10:13) = [1; 0; 0; 0];
trueError = zeros(19,1);
trueError(10:12) = deg2rad([0.2; -0.2; 2]);
xTrue = state_injection(xNominal, trueError);

% Measurements from the sim models at truth
t = 0.1;
meas_posvel = gps_model(xTrue, t, gps_frame);
[~, meas_angvel] = imu_model(xTrue, zeros(3,1), zeros(3,1), zeros(3,1), t);
meas_baro = barometer_model(xTrue, 0, t);
meas_LID = lidar_system_model(xTrue, t, lidar_frames);
meas_diffGps = diffGps_model(xTrue, t, gps_frame);
aux = struct();

% Step with DGPS
clear gmekf_correct_hopper
[xWith, PWith] = gmekf_correct_hopper(xNominal, P0, aux, meas_posvel, ...
    meas_angvel, meas_baro, meas_LID, lidar_frames, meas_diffGps, gps_frame);

% Same step with DGPS marked invalid
meas_noDiffGps = meas_diffGps;
meas_noDiffGps.validity = false;
clear gmekf_correct_hopper
[xWithout, PWithout] = gmekf_correct_hopper(xNominal, P0, aux, meas_posvel, ...
    meas_angvel, meas_baro, meas_LID, lidar_frames, meas_noDiffGps, gps_frame);
clear gmekf_correct_hopper

errBefore = rad2deg(attitude_error(xNominal, xTrue));
errWith = rad2deg(attitude_error(xWith, xTrue));
errWithout = rad2deg(attitude_error(xWithout, xTrue));
stdWith = rad2deg(sqrt(diag(PWith(10:12,10:12))));
stdWithout = rad2deg(sqrt(diag(PWithout(10:12,10:12))));
[~, notPD] = chol(PWith);

fprintf('state %s, covariance %s, symmetric err %.1e, PD = %d\n', ...
    mat2str(size(xWith)), mat2str(size(PWith)), max(abs(PWith - PWith'), [], 'all'), notPD == 0);
fprintf('attitude error [x y z] deg\n');
fprintf('   before          = [%7.3f %7.3f %7.3f]\n', errBefore);
fprintf('   after, no DGPS  = [%7.3f %7.3f %7.3f]\n', errWithout);
fprintf('   after, DGPS     = [%7.3f %7.3f %7.3f]\n', errWith);
fprintf('attitude 1-sigma [x y z] deg\n');
fprintf('   after, no DGPS  = [%7.3f %7.3f %7.3f]\n', stdWithout);
fprintf('   after, DGPS     = [%7.3f %7.3f %7.3f]\n', stdWith);
fprintf('position change with DGPS = %.2e m\n', norm(xWith(1:3) - xWithout(1:3)));

Simulink.data.dictionary.closeAll('-discard');
cd(startDir);

%% Pass/fail
checks = { ...
    'all LIDAR beams valid (LIDAR path exercised)', all(meas_LID.validity);
    'output sizes', isequal(size(xWith), [20 1]) && isequal(size(PWith), [19 19]);
    'covariance symmetric', max(abs(PWith - PWith'), [], 'all') < 1e-12;
    'covariance positive definite', notPD == 0;
    'quaternion unit norm', abs(norm(xWith(10:13)) - 1) < 1e-12;
    'roll (z) kept without DGPS', abs(errWithout(3) - errBefore(3)) < 0.1*abs(errBefore(3));
    'roll (z) removed with DGPS', abs(errWith(3)) < 0.05*abs(errBefore(3));
    'roll (z) sigma reduced by DGPS', stdWith(3) < 0.1*stdWithout(3)};
fprintf('\n');
for i = 1:size(checks,1)
    if checks{i,2}, tag = 'PASS'; else, tag = 'FAIL'; end
    fprintf('  [%s] %s\n', tag, checks{i,1});
end
assert(all([checks{:,2}]), 'test_gmekf_correct_hopper: one or more checks failed');
fprintf('test_gmekf_correct_hopper: all checks passed\n');

%% Helpers
function phi = attitude_error(xEstimate, xTrue)
% Small-angle rotation vector of C_BI_estimate' * C_BI_true, i.e. the
% dtheta that state_injection would need to reach truth
    E = quaternion_to_rotation(xEstimate(10:13))' * quaternion_to_rotation(xTrue(10:13));
    phi = 0.5 * [E(3,2) - E(2,3); E(1,3) - E(3,1); E(2,1) - E(1,2)];
end
